WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_basic_etiquette'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '礼仪与气场', 'kp-ms-basic-etiquette', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "面试礼仪与气场"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "首因效应：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "考官对你的第一印象在进门的前 10 秒就已经注定。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心细节"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "敲门与步伐：敲门三声，停顿后进入。步伐稳健，不拖沓，不左顾右盼。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "眼神交流：答题时必须环视全场考官，尤其是主考官。切忌低头念稿或死死盯着天花板。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "坐姿与手势：只坐椅子的前 2/3，腰背挺直。双手自然交叠放于桌上，可以有轻微的辅助手势，绝不能转笔、抖腿。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、气场修炼"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所谓气场，就是“去学生气，养机关气”。答题声音要洪亮、坚定，即使忘词也要从容过渡。把考场当成你在汇报工作，而不是在背书。"}]}]}$$ AS jsonb), NULL, '礼仪与气场的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "基础素养", "礼仪"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_basic_etiquette", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
